const cfg = $('Set winner').first().json;
const market = ($json.markets || [])[0];
if (!market) throw new Error('No open market to settle.');
const outcome = market.outcomes.find(o => o.label.toLowerCase() === cfg.winnerName.toLowerCase());
if (!outcome) throw new Error('Winner not found. Options: ' + market.outcomes.map(o => o.label).join(', '));
return [{ json: { marketId: market.id, title: market.title, outcomeId: outcome.id, winnerName: outcome.label, apiBase: cfg.apiBase } }];
